describe("doctests of sympy.matrices.subspaces", () => {
  it("M.rowspace()", () => {
    const v1 = rowspace(Matrix.of([[Rational.of(1n, 1n, { gcd: 1n }), Rational.of(3n, 1n, { gcd: 1n }), Rational.of(0n, 1n, { gcd: 1n })], [Rational.of(-2n, 1n, { gcd: 1n }), Rational.of(-6n, 1n, { gcd: 1n }), Rational.of(0n, 1n, { gcd: 1n })], [Rational.of(3n, 1n, { gcd: 1n }), Rational.of(9n, 1n, { gcd: 1n }), Rational.of(6n, 1n, { gcd: 1n })]]));
    expect(sympyStr([at(v1, 0), at(v1, 1)])).toBe('[Matrix([[1, 3, 0]]), Matrix([[0, 0, 6]])]');
  });
  it("M.columnspace()", () => {
    const v1 = columnspace(Matrix.of([[Rational.of(1n, 1n, { gcd: 1n }), Rational.of(3n, 1n, { gcd: 1n }), Rational.of(0n, 1n, { gcd: 1n })], [Rational.of(-2n, 1n, { gcd: 1n }), Rational.of(-6n, 1n, { gcd: 1n }), Rational.of(0n, 1n, { gcd: 1n })], [Rational.of(3n, 1n, { gcd: 1n }), Rational.of(9n, 1n, { gcd: 1n }), Rational.of(6n, 1n, { gcd: 1n })]]));
    expect(sympyMatches([at(v1, 0), at(v1, 1)], '[Matrix([\n[ 1],\n[-2],\n[ 3]]), Matrix([\n[0],\n[0],\n[6]])]')).toBe(true);
  });
  it("M.nullspace()", () => {
    expect(sympyMatches([at(nullspace(Matrix.of([[Rational.of(1n, 1n, { gcd: 1n }), Rational.of(3n, 1n, { gcd: 1n }), Rational.of(0n, 1n, { gcd: 1n })], [Rational.of(-2n, 1n, { gcd: 1n }), Rational.of(-6n, 1n, { gcd: 1n }), Rational.of(0n, 1n, { gcd: 1n })], [Rational.of(3n, 1n, { gcd: 1n }), Rational.of(9n, 1n, { gcd: 1n }), Rational.of(6n, 1n, { gcd: 1n })]])), 0)], '[Matrix([\n[-3],\n[ 1],\n[ 0]])]')).toBe(true);
  });
  it("M", () => {
    expect(sympyStr(Matrix.row(Rational.of(1n, 1n, { gcd: 1n }), Rational.of(3n, 1n, { gcd: 1n }), Rational.of(0n, 1n, { gcd: 1n }), Rational.of(-2n, 1n, { gcd: 1n }), Rational.of(-6n, 1n, { gcd: 1n }), Rational.of(0n, 1n, { gcd: 1n }), Rational.of(3n, 1n, { gcd: 1n }), Rational.of(9n, 1n, { gcd: 1n }), Rational.of(6n, 1n, { gcd: 1n })).reshape(3, 3))).toBe('Matrix([[1, 3, 0], [-2, -6, 0], [3, 9, 6]])');
  });
  it("M (2)", () => {
    expect(sympyStr(Matrix.row(Rational.of(1n, 1n, { gcd: 1n }), Rational.of(3n, 1n, { gcd: 1n }), Rational.of(0n, 1n, { gcd: 1n }), Rational.of(-2n, 1n, { gcd: 1n }), Rational.of(-6n, 1n, { gcd: 1n }), Rational.of(0n, 1n, { gcd: 1n }), Rational.of(3n, 1n, { gcd: 1n }), Rational.of(9n, 1n, { gcd: 1n }), Rational.of(6n, 1n, { gcd: 1n })).reshape(3, 3))).toBe('Matrix([[1, 3, 0], [-2, -6, 0], [3, 9, 6]])');
  });
  it("M (3)", () => {
    expect(sympyStr(Matrix.row(Rational.of(1n, 1n, { gcd: 1n }), Rational.of(3n, 1n, { gcd: 1n }), Rational.of(0n, 1n, { gcd: 1n }), Rational.of(-2n, 1n, { gcd: 1n }), Rational.of(-6n, 1n, { gcd: 1n }), Rational.of(0n, 1n, { gcd: 1n }), Rational.of(3n, 1n, { gcd: 1n }), Rational.of(9n, 1n, { gcd: 1n }), Rational.of(6n, 1n, { gcd: 1n })).reshape(3, 3))).toBe('Matrix([[1, 3, 0], [-2, -6, 0], [3, 9, 6]])');
  });
});

